db.exec('CREATE TABLE t (a INTEGER, b TEXT)');
const ins = db.prepare('INSERT INTO t VALUES (?, ?)');
for (let i = 0; i < 500; i++) ins.run(i, 'x'.repeat(64));
let sink = [];
for (let i = 0; i < 200000; i++) {
  // a fresh prepared statement every iteration -> garbage Statement wrappers
